    private BlobSvm() {
    }

    /**
     * The SVM's decision value, sklearn's {@code decision_function}: positive
     * leans ball.
     *
     * @param features raw features in {@link #FEATURES} order; NaN is imputed
     */
    public static double decision(double[] features) {
        double[] z = new double[N_FEATURES];
        for (int j = 0; j < N_FEATURES; j++) {
            double v = Double.isNaN(features[j]) ? IMPUTE[j] : features[j];
            z[j] = (v - MEAN[j]) / SCALE[j];
        }
        double sum = INTERCEPT;
        for (int i = 0; i < SV.length; i++) {
            double[] s = SV[i];
            double d2 = 0;
            for (int j = 0; j < N_FEATURES; j++) {
                double t = z[j] - s[j];
                d2 += t * t;
            }
            sum += DUAL[i] * Math.exp(-GAMMA * d2);
        }
        return sum;
    }

    /** P(ball), as sklearn's {@code predict_proba(X)[:, 1]}. */
    public static double probability(double[] features) {
        return probabilityFromDecision(decision(features));
    }

    /**
     * libsvm's svm_predict_probability for two classes: the Platt sigmoid on
     * libsvm's decision value (the negative of sklearn's), clipped, then the
     * pairwise-coupling iteration, which for two classes stops early and so
     * does not return the sigmoid unchanged.
     */
    static double probabilityFromDecision(double sklearnDecision) {
        double dec = -sklearnDecision;                 // libsvm's sign: positive = class 0 (not ball)
        double fApB = dec * PROB_A + PROB_B;
        double r01 = fApB >= 0 ? Math.exp(-fApB) / (1.0 + Math.exp(-fApB))
                               : 1.0 / (1.0 + Math.exp(fApB));
        r01 = Math.min(Math.max(r01, MIN_PROB), 1 - MIN_PROB);
        double r10 = 1 - r01;

        // multiclass_probability, k = 2. r[0][1] = r01, r[1][0] = r10.
        double q00 = r10 * r10, q11 = r01 * r01;
        double q01 = -r10 * r01, q10 = q01;
        double p0 = 0.5, p1 = 0.5;
        final double eps = 0.005 / 2;
        double qp0, qp1, pQp;
        for (int iter = 0; iter < 100; iter++) {
            qp0 = q00 * p0 + q01 * p1;
            qp1 = q10 * p0 + q11 * p1;
            pQp = p0 * qp0 + p1 * qp1;
            if (Math.max(Math.abs(qp0 - pQp), Math.abs(qp1 - pQp)) < eps) {
                break;
            }
            // t = 0
            double diff = (-qp0 + pQp) / q00;
            p0 += diff;
            pQp = (pQp + diff * (diff * q00 + 2 * qp0)) / (1 + diff) / (1 + diff);
            qp0 = (qp0 + diff * q00) / (1 + diff);
            qp1 = (qp1 + diff * q10) / (1 + diff);
            p0 /= (1 + diff);
            p1 /= (1 + diff);
            // t = 1
            diff = (-qp1 + pQp) / q11;
            p1 += diff;
            pQp = (pQp + diff * (diff * q11 + 2 * qp1)) / (1 + diff) / (1 + diff);
            qp0 = (qp0 + diff * q01) / (1 + diff);
            qp1 = (qp1 + diff * q11) / (1 + diff);
            p0 /= (1 + diff);
            p1 /= (1 + diff);
        }
        return p1;
    }
